# -*- coding: utf-8 -*-
"""
mentor_flags.py — marca no banco o que é BASE (por aula) e o MODO de cada assunto, conforme o edital v3
(BASE_POR_MATERIA_E_CRONOGRAMA.md, 2ª passada de 26/09/2026). Não recarrega nada: só ALTER + UPDATE.
Não apaga resposta, revisão, sessão, progresso, caderno nem cards.

O que faz:
  1. colunas novas: aula.base, materia.fase/trilha/trilha_ordem/regua_base/prova_base_em, plano_item.modo/aulas; tabela mentor.prova_base
  2. move "Preâmbulo e Princípios Fundamentais" e "Direitos e Deveres Individuais e Coletivos" (curso de Igualdade) pra Direito Constitucional
  3. cria o assunto próprio "Crime militar em tempo de paz — art. 9º do CPM" em Penal Militar
  4. marca base=true nas 227 aulas da base, modo em cada assunto, trilha e régua em cada matéria
  5. grava os 8 resumos próprios como resumo_bolso das aulas próprias
  6. config: trilhas e pesos do planejador

Uso (na pasta do tipmike_api, no .venv):
  python mentor_flags.py --simular      # mostra o que faria e desfaz (rollback)
  python mentor_flags.py                # aplica (commit)
DSN: MIKEDB_DSN no ambiente ou no .env; senão o padrão do repo.
"""
import argparse, base64, gzip, json, os, sys

try:
    import psycopg2
    import psycopg2.extras as ex
except ImportError:
    print("instale: pip install psycopg2-binary"); sys.exit(1)

DSN_PADRAO = "postgresql://postgres:mikedb0702@localhost:5432/mikedb"
PAYLOAD_B64 = ""


def dsn():
    d = os.environ.get("MIKEDB_DSN")
    if not d and os.path.exists(".env"):
        for ln in open(".env", encoding="utf-8"):
            if ln.strip().startswith("MIKEDB_DSN="):
                d = ln.strip().split("=", 1)[1].strip().strip('"').strip("'")
    return d or DSN_PADRAO


def payload():
    return json.loads(gzip.decompress(base64.b64decode(PAYLOAD_B64)).decode("utf-8"))


DDL = [
    "ALTER TABLE mentor.aula ADD COLUMN IF NOT EXISTS base BOOLEAN NOT NULL DEFAULT FALSE",
    "CREATE INDEX IF NOT EXISTS ix_aula_base ON mentor.aula(assunto_id) WHERE base",
    "ALTER TABLE mentor.materia ADD COLUMN IF NOT EXISTS fase TEXT NOT NULL DEFAULT 'base'",
    "ALTER TABLE mentor.materia ADD COLUMN IF NOT EXISTS trilha TEXT",
    "ALTER TABLE mentor.materia ADD COLUMN IF NOT EXISTS trilha_ordem INT",
    "ALTER TABLE mentor.materia ADD COLUMN IF NOT EXISTS regua_base INT NOT NULL DEFAULT 60",
    "ALTER TABLE mentor.materia ADD COLUMN IF NOT EXISTS prova_base_em TIMESTAMPTZ",
    "ALTER TABLE mentor.plano_item ADD COLUMN IF NOT EXISTS modo TEXT",
    "ALTER TABLE mentor.plano_item ADD COLUMN IF NOT EXISTS aulas BIGINT[]",
    """CREATE TABLE IF NOT EXISTS mentor.prova_base (
        id BIGSERIAL PRIMARY KEY,
        materia_id INT NOT NULL REFERENCES mentor.materia(id) ON DELETE CASCADE,
        questoes BIGINT[] NOT NULL,
        respostas JSONB,
        certas INT, n INT, acerto NUMERIC(5,2), regua INT,
        aprovada BOOLEAN,
        aulas_erradas BIGINT[],
        sessao_id BIGINT REFERENCES mentor.sessao(id) ON DELETE SET NULL,
        inicio TIMESTAMPTZ NOT NULL DEFAULT now(), fim TIMESTAMPTZ)""",
    "CREATE INDEX IF NOT EXISTS ix_prova_base_mat ON mentor.prova_base(materia_id, inicio DESC)",
]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--simular", action="store_true", help="roda tudo e desfaz (rollback)")
    ap.add_argument("--dsn", default=None)
    args = ap.parse_args()
    P = payload()
    con = psycopg2.connect(args.dsn or dsn())
    con.autocommit = False
    cur = con.cursor()
    rel = []
    try:
        for sql in DDL:
            cur.execute(sql)
        rel.append("colunas e tabela: ok")

        # ---- 2. movidos (Igualdade -> Constitucional)
        for mv in P.get("movidos", []):
            cur.execute("SELECT id FROM mentor.modulo WHERE materia_id=%s AND ordem=%s", (mv["para_materia"], mv["modulo"]["ordem"]))
            r = cur.fetchone()
            if r:
                mod_id = r[0]
            else:
                cur.execute("INSERT INTO mentor.modulo (materia_id, ordem, nome, tipo) VALUES (%s,%s,%s,%s) RETURNING id",
                            (mv["para_materia"], mv["modulo"]["ordem"], mv["modulo"]["nome"], mv["modulo"]["tipo"]))
                mod_id = cur.fetchone()[0]
            n = 0
            for i, nome in enumerate(mv["assuntos"], 1):
                cur.execute("UPDATE mentor.assunto SET materia_id=%s, modulo_id=%s, ordem=%s WHERE materia_id=%s AND nome=%s RETURNING id",
                            (mv["para_materia"], mod_id, i, mv["de_materia"], nome))
                n += cur.rowcount
                # já movido em rodada anterior? garante a ordem
                cur.execute("UPDATE mentor.assunto SET ordem=%s WHERE modulo_id=%s AND nome=%s", (i, mod_id, nome))
            rel.append(f"movidos pra matéria {mv['para_materia']}: {n} assunto(s) nesta rodada")

        # ---- 3. novos (art. 9º do CPM)
        for nv in P.get("novos", []):
            mo, a = nv["modulo"], nv["assunto"]
            cur.execute("SELECT id FROM mentor.modulo WHERE materia_id=%s AND ordem=%s", (nv["materia_id"], mo["ordem"]))
            r = cur.fetchone()
            if r:
                mod_id = r[0]
            else:
                cur.execute("INSERT INTO mentor.modulo (materia_id, ordem, nome, tipo) VALUES (%s,%s,%s,%s) RETURNING id", (nv["materia_id"], mo["ordem"], mo["nome"], mo["tipo"]))
                mod_id = cur.fetchone()[0]
            cur.execute("SELECT id FROM mentor.assunto WHERE materia_id=%s AND nome=%s", (nv["materia_id"], a["nome"]))
            r = cur.fetchone()
            if r:
                ass_id = r[0]
                rel.append(f"assunto próprio já existia: {a['nome']}")
            else:
                cur.execute("""INSERT INTO mentor.assunto (materia_id, modulo_id, ordem, nome, tier, modo, base, origem, descricao, etiquetas)
                               VALUES (%s,%s,%s,%s,%s,%s,TRUE,%s,%s,%s) RETURNING id""",
                            (nv["materia_id"], mod_id, a["ordem"], a["nome"], a["tier"], a["modo"], a["origem"], a["descricao"], a["etiquetas"]))
                ass_id = cur.fetchone()[0]
                cur.execute("INSERT INTO mentor.aula (assunto_id, ordem, tipo, titulo, etiquetas, lei, base) VALUES (%s,1,'propria',%s,%s,%s,TRUE)",
                            (ass_id, a["nome"], a["etiquetas"], a["descricao"]))
                rel.append(f"assunto próprio criado: {a['nome']}")

        # ---- 4. base / modo / trilhas
        tot_base = tot_aulas = tot_ass = 0
        faltou = []
        for m in P["materias"]:
            cur.execute("UPDATE mentor.materia SET trilha=%s, trilha_ordem=%s, regua_base=%s WHERE id=%s", (m["trilha"], m["trilha_ordem"], m["regua_base"], m["id"]))
            nb = na = 0
            for a in m["assuntos"]:
                cur.execute("""SELECT s.id FROM mentor.assunto s JOIN mentor.modulo mo ON mo.id=s.modulo_id
                               WHERE s.materia_id=%s AND mo.ordem=%s AND s.ordem=%s""", (m["id"], a["mo"], a["ordem"]))
                r = cur.fetchone()
                if not r:
                    cur.execute("SELECT id FROM mentor.assunto WHERE materia_id=%s AND nome=%s", (m["id"], a["nome"]))
                    r = cur.fetchone()
                if not r:
                    faltou.append(f"{m['nome']}: {a['nome']}")
                    continue
                ass_id = r[0]
                tot_ass += 1
                cur.execute("UPDATE mentor.assunto SET modo=%s WHERE id=%s", (a["modo"], ass_id))
                if a["origem"] == "propria" and not a["aulas"]:
                    cur.execute("UPDATE mentor.aula SET base=%s WHERE assunto_id=%s AND tipo='propria'", (bool(a["aula_base"]), ass_id))
                    nb += cur.rowcount if a["aula_base"] else 0
                    na += cur.rowcount
                for cod, ordem, titulo, base in a["aulas"]:
                    if cod:
                        cur.execute("UPDATE mentor.aula SET base=%s WHERE codigo_aula=%s", (bool(base), cod))
                    else:
                        cur.execute("UPDATE mentor.aula SET base=%s WHERE assunto_id=%s AND ordem=%s", (bool(base), ass_id, ordem))
                    if cur.rowcount == 0:
                        cur.execute("UPDATE mentor.aula SET base=%s WHERE assunto_id=%s AND titulo=%s", (bool(base), ass_id, titulo))
                    if cur.rowcount == 0:
                        faltou.append(f"{m['nome']}: aula {cod or ordem} {titulo[:40]}")
                        continue
                    na += 1
                    nb += bool(base)
            # fase: quem não tem base já nasce em modo questão; quem já passou na prova de base fica como está
            cur.execute("SELECT count(*) FROM mentor.aula a JOIN mentor.assunto s ON s.id=a.assunto_id WHERE s.materia_id=%s AND a.base", (m["id"],))
            n_base_db = cur.fetchone()[0]
            if n_base_db == 0:
                cur.execute("UPDATE mentor.materia SET fase='questao' WHERE id=%s AND prova_base_em IS NULL", (m["id"],))
            tot_base += nb
            tot_aulas += na
            rel.append(f"{m['id']:2} {m['nome'][:26]:26} trilha {m['trilha']}{m['trilha_ordem']} régua {m['regua_base']}  base {nb:3} de {na:3} aulas  (no banco: {n_base_db})")

        # ---- 5. resumos próprios
        nr = 0
        for rs in P["resumos"]:
            cur.execute("""UPDATE mentor.aula a SET resumo_bolso=%s, base=TRUE FROM mentor.assunto s
                           WHERE a.assunto_id=s.id AND s.materia_id=%s AND s.nome=%s AND a.tipo='propria'""", (rs["texto"], rs["materia_id"], rs["assunto"]))
            if cur.rowcount == 0:
                # a aula própria pode ter o título do assunto
                cur.execute("""UPDATE mentor.aula a SET resumo_bolso=%s, base=TRUE FROM mentor.assunto s
                               WHERE a.assunto_id=s.id AND s.materia_id=%s AND a.titulo=%s""", (rs["texto"], rs["materia_id"], rs["assunto"]))
            if cur.rowcount == 0:
                faltou.append(f"resumo sem aula: {rs['assunto']}")
            nr += cur.rowcount
        rel.append(f"resumos próprios gravados: {nr}")

        # ---- 6. config
        for k, v in (("trilhas", P["trilhas"]), ("pesos_trilha", P["pesos_trilha"]), ("edital_versao", 3)):
            cur.execute("INSERT INTO mentor.config (chave, valor) VALUES (%s,%s) ON CONFLICT (chave) DO UPDATE SET valor=EXCLUDED.valor, alterado_em=now()", (k, json.dumps(v)))
        rel.append(f"TOTAL: {tot_base} aulas de base em {tot_aulas} conferidas, {tot_ass} assuntos com modo")
        if faltou:
            rel.append("NÃO ENCONTRADOS (conferir): " + " | ".join(faltou[:30]))
        print("\n".join(rel))
        if args.simular:
            con.rollback()
            print("\n[simulação] nada gravado (rollback)")
        else:
            con.commit()
            print("\ngravado (commit). Agora: reiniciar a API com o routers/mentor.py v3.8 e, no painel, o Planejamento mostra 'Base por matéria'.")
    except Exception as e:
        con.rollback()
        print("ERRO — nada gravado:", repr(e))
        raise
    finally:
        con.close()


if __name__ == "__main__":
    main()
